function npcRoleLabel(role:string){const copy=npcCopy[locale],labels:Record<string,string>={"item-shop":copy.itemShopRole,"bounty-exchange":copy.itemShopRole,"arena-exchange":copy.itemShopRole,"pal-shop":copy.palShopRole,"achievement-reward":copy.achievementRole,"item-request":copy.itemRequestRole,"pal-request":copy.palRequestRole,quest:copy.questRole,guide:copy.guideRole,dialogue:copy.dialogueRole,combat:copy.combatRole,"emote-reward":copy.emoteRole,"bounty-intel":copy.bountyIntelRole,gift:copy.giftRole,character:copy.characterRole};return labels[role]||copy.characterRole}
