function selectedMapWorld(){const requested=new URLSearchParams(location.search).get("world")==="tree"?"tree":"palpagos";return mapData?.worlds?.find(world=>world.id===requested)||mapData?.worlds?.[0]||null}
function gameMapCoordinates(worldX:number,worldY:number){return {x:(worldY-158000)/459,y:(worldX+123888)/459}}
function mapImagePosition(bounds:Pick<MapWorld,"minX"|"minY"|"maxX"|"maxY">,worldX:number,worldY:number){return {left:(worldY-bounds.minY)/(bounds.maxY-bounds.minY)*100,top:(bounds.maxX-worldX)/(bounds.maxX-bounds.minX)*100}}
function mapWorldPosition(bounds:Pick<MapWorld,"minX"|"minY"|"maxX"|"maxY">,pixelX:number,pixelY:number){return {x:bounds.maxX-pixelY/8192*(bounds.maxX-bounds.minX),y:bounds.minY+pixelX/8192*(bounds.maxY-bounds.minY)}}
