function serverPage(){const extra=uiCopy[locale];setMeta(m.serverTitle,extra.serverNotice);const groupNames={management:extra.serverManagement,performance:extra.serverPerformance,features:extra.serverFeatures,balance:extra.serverBalance},serverPlaceholders:Record<string,string>={ServerName:extra.serverNamePlaceholder,ServerDescription:extra.serverDescriptionPlaceholder,ServerPassword:extra.passwordRequiredPlaceholder,AdminPassword:extra.adminPasswordPlaceholder};const fields=(group:keyof typeof groupNames)=>officialServerSettings.filter(setting=>setting.group===group).map(setting=>{const value=setting.defaultValue,attrs=`${setting.min!==undefined?` min="${setting.min}"`:""}${setting.max!==undefined?` max="${setting.max}"`:""}${setting.step!==undefined?` step="${setting.step}"`:setting.type==="number"?' step="any"':""}`,placeholder=setting.placeholder?` placeholder="${esc(serverPlaceholders[setting.key]||setting.placeholder)}"`:"";if(setting.type==="boolean")return `<label class="server-setting check"><input name="${setting.key}" type="checkbox" data-server-key ${value===true?"checked":""}><span><strong>${setting.key}</strong></span></label>`;if(setting.type==="enum")return `<label class="server-setting"><strong>${setting.key}</strong><select name="${setting.key}" data-server-key><option value="">${m.choose}</option>${setting.options?.map(option=>`<option value="${option}">${option}</option>`).join("")}</select></label>`;if((setting.type==="integer"||setting.type==="number")&&setting.min!==undefined&&setting.max!==undefined)return `<label class="server-setting server-range"><strong>${setting.key}</strong><span class="range-pair"><input type="range" min="${setting.min}" max="${setting.max}" step="${setting.step??(setting.type==="integer"?1:"any")}" value="${value??setting.min}" data-range-for="${setting.key}" aria-label="${setting.key}"><input name="${setting.key}" data-server-key type="number"${attrs}${placeholder} value="${value??""}"></span><small>${setting.min.toLocaleString(locale)} – ${setting.max.toLocaleString(locale)}</small></label>`;return `<label class="server-setting"><strong>${setting.key}</strong><input name="${setting.key}" data-server-key type="${setting.sensitive?"password":setting.type==="text"?"text":"number"}"${attrs}${placeholder} value="${value??""}"></label>`}).join("");return `${hero(m.serverTitle,m.footer)}<section class="tool-layout server content-shell"><div><form class="panel server-form" id="server-form">${(Object.keys(groupNames) as (keyof typeof groupNames)[]).map(group=>`<fieldset><legend>${groupNames[group]}</legend><div class="server-setting-grid">${fields(group)}</div></fieldset>`).join("")}<button class="button primary">${m.generate}</button></form><div class="panel server-import"><label>${extra.importExistingIni}<textarea id="ini-import" autocomplete="off" spellcheck="false"></textarea></label><button class="button" id="import-ini" type="button">${extra.importAndValidate}</button><div id="ini-warnings" class="notice" role="status" hidden></div></div></div><div class="panel output-panel"><textarea id="ini-output" aria-label="${extra.iniOutput}" readonly></textarea><p class="notice">${extra.serverNotice}</p><button class="button" id="copy-ini">${m.copy}</button></div></section>`}
function placeholder(title:string):string{const current=route();if(current==="/database/npcs")return npcCollectionPage();if(current==="/database/dungeons")return dungeonCollectionPage();if(current==="/database/expeditions")return expeditionCollectionPage();if(current==="/database/quests")return questCollectionPage();if(current==="/database/health")return healthCollectionPage();const healthMatch=current.match(/^\/database\/health\/conditions\/([^/]+)$/);if(healthMatch&&(!healthData||healthData.conditions.some(condition=>condition.slug===decodeURIComponent(healthMatch[1]))))return healthConditionDetail(decodeURIComponent(healthMatch[1]));const npcMatch=current.match(/^\/database\/npcs\/([^/]+)$/);if(npcMatch&&(!npcData||npcData.npcs.some(npc=>npc.slug===decodeURIComponent(npcMatch[1]))))return npcDetail(decodeURIComponent(npcMatch[1]));const dungeonMatch=current.match(/^\/database\/dungeons\/([^/]+)$/);if(dungeonMatch&&(!dungeonData||dungeonData.dungeons.some(dungeon=>dungeon.slug===decodeURIComponent(dungeonMatch[1]))))return dungeonDetail(decodeURIComponent(dungeonMatch[1]));const expeditionMatch=current.match(/^\/database\/expeditions\/([^/]+)$/);if(expeditionMatch&&(!expeditionData||expeditionData.expeditions.some(expedition=>expedition.slug===decodeURIComponent(expeditionMatch[1]))))return expeditionDetail(decodeURIComponent(expeditionMatch[1]));const questMatch=current.match(/^\/database\/quests\/([^/]+)$/);if(questMatch&&(!questData||questData.quests.some(quest=>quest.slug===decodeURIComponent(questMatch[1]))))return questDetail(decodeURIComponent(questMatch[1]));document.title=`${title} · ${site.name}`;document.querySelectorAll("[data-dynamic-meta]").forEach(node=>node.remove());if(title==="404"){const robots=document.createElement("meta");robots.name="robots";robots.content="noindex, nofollow";robots.dataset.dynamicMeta="true";document.head.append(robots)}return `${hero(title,m.coming)}<section class="section"><div class="empty-large"><span>◇</span><p>${m.coming}</p></div></section>`}
function partnerSkillDetail(segment:string){const skill=skillData?resolveEntitySegment("partnerSkills",segment,skillData.partnerSkills,"skills/partner"):null,pal=data?.pals.find(entry=>entry.id===skill?.palId);if(!skill||!pal)return data&&skillData?placeholder("404"):"";const title=partnerSkillName(skill,pal),description=localizedName(skill.palDescriptions);setMeta(title,description||partnerLabel[locale]);return `${hero(title,partnerLabel[locale])}<article class="entity-detail panel">${pal.image?`<img class="detail-image" src="/assets/pals/${encodeURIComponent(pal.id)}.png" alt="${esc(palName(pal))}">`:""}<div class="entity-detail-content">${description?`<p class="entity-description">${esc(description)}</p>`:""}<p><a class="button" href="${href(`/pals/${encodeURIComponent(pal.id)}`)}" data-link>${esc(palName(pal))}</a></p></div></article>`}
function content(){
  const current=route(),palMatch=current.match(/^\/pals\/([^/]+)$/),itemMatch=current.match(/^\/items\/([^/]+)$/),dungeonMatch=current.match(/^\/database\/dungeons\/([^/]+)$/),expeditionMatch=current.match(/^\/database\/expeditions\/([^/]+)$/),questMatch=current.match(/^\/database\/quests\/([^/]+)$/),technologyMatch=current.match(/^\/database\/technology\/([^/]+)$/),structureMatch=current.match(/^\/database\/structures\/([^/]+)$/),skillMatch=current.match(/^\/skills\/(active|passive)\/([^/]+)$/),partnerMatch=current.match(/^\/skills\/partner\/([^/]+)$/),skillCollection=current.match(/^\/skills\/(active|passive|partner)$/);
  if(current==="/privacy")return privacyPage();
  if(palMatch)return palDetail(decodeURIComponent(palMatch[1]));
  if(itemMatch)return itemDetail(decodeURIComponent(itemMatch[1]));
  if(dungeonMatch)return dungeonDetail(decodeURIComponent(dungeonMatch[1]));
  if(expeditionMatch)return expeditionDetail(decodeURIComponent(expeditionMatch[1]));
  if(questMatch)return questDetail(decodeURIComponent(questMatch[1]));
  if(technologyMatch)return technologyDetail(decodeURIComponent(technologyMatch[1]));
  if(structureMatch)return structureDetail(decodeURIComponent(structureMatch[1]));
  if(partnerMatch)return partnerSkillDetail(decodeURIComponent(partnerMatch[1]));
  if(skillMatch)return skillDetail(skillMatch[1],decodeURIComponent(skillMatch[2]));
  if(!knownCollectionRoutes.has(current))return placeholder("404");
  if(skillCollection)return skillsCategoryPage(skillCollection[1] as "active"|"passive"|"partner");
  switch(current){case"/":return home();case"/pals":return palsPage();case"/skills":return `${skillsPage().replace('<section class="section">',`<section class="section">${skillTabs()}`)}`;case"/calculators":case"/calculators/breeding":return breedingPage();case"/calculators/crafting":return craftingPage();case"/calculators/base":return basePlannerPage();case"/server-tools/settings-generator":return serverPage();case"/map":return mapPage();case"/database":return databasePage();case"/database/quests":return questCollectionPage();case"/database/structures":return structureCollectionPage();case"/database/expeditions":return expeditionCollectionPage();case"/database/elements":return elementCollectionPage();case"/database/technology":return technologyCollectionPage();case"/database/dungeons":return dungeonCollectionPage();default:return placeholder("404")}
}
